/*
 * BP+ Simulator class.
 */
class BpPlusSimulator {
 
  /*
   * Create simulator instance
   */
  constructor() {
    // Private variables
    this._event = new Emitter;
    this._timer = 500; // The timer for the simulated events
    this._timerHandle;
    this._counter = 0;
    this._running = false;
    this._status = 'disconnected';
  }

  status() {
    return this._status;
  }
  
  register(type, fn) {
    this._event.on(type, fn);
  }

  connect() {
    console.log('connect');
    this._status = 'connected';
    this._event.emit('connect', true);
  }

  disconnect() {
    this._status = 'disconnected';
    this._event.emit('connect', false);
  }

  start() {
    this._status = 'running';
  
    if (this._running) {
      this.stop();
    }
    else {
      this._running = true;
      this._counter = 0;
      
      // Start the timer
      this._counter = 0;
      this._timerHandle = setInterval(this._timerProcess.bind(this), this._timer);
    }
  }

  cancel() {
    clearTimeout(this._timerHandle);      

    this._notifyString('receive', 'M 02\r\n');
  }

  stop() {
    this._status = 'connected';
    this._running = false;
    this._event.emit('stop', true);

    // Stop the timer
    clearTimeout(this._timerHandle);      
  }
  
  receive(data) {
  }
 
  _notifyString(type, bufferString) {
    let uint8Array = new TextEncoder("utf-8").encode(bufferString);
    this._event.emit(type, uint8Array);
  }
  
  _timerProcess() {
    // Work out the next event and receive it
    const count = this._counter++;
    //console.log("timer" + count);
    
    if (count == 0) {
      this._notifyString('receive', 'M 03\r\n');
      this._notifyString('receive', 'P 000\r\n');
    }
    else if (count == 1) {
      // Send a partial line
      this._notifyString('receive', 'P 010\r\nP 0');
    }
    else if (count == 2) {
      // send the rest of the partial above
      this._notifyString('receive', '20\r\n');
    }
    else if (count < 10) {
      this._notifyString('receive', 'P 0' + (count * 10) + '\r\n');
      //this.receive('P ' + count);
    }
    
    if (count == 10) {
      this._notifyString('receive', 'M 04\r\n');
      this._notifyString('receive', 'M 05\r\n');
      
    }
    else if (count == 11) {
      // Send the result
      this._notifyString('receive', 'M 06\r\n');
      this._notifyString('receive', 'M 07\r\n');
      /*
      this._notifyString('receive', 'S 00000 016 122 095 074 044 116 094 075 046 059 072 005 325 160 175 0659\r\n');
      this._notifyString('receive', 'M 02\r\n');
      */

      // Update the time to now
      //var dateString = new Date().toISOString().substr(0, 19); this works well but time is in UTC not local  
      //var dateString = '' + date.getFullYear() + '-' + ("0" + (date.getDate()+1)).slice(-2) + '-' + ("0" + date.getDate()).slice(-2) + 'T' + date.getHours();
      var date = new Date();
      var dateString = date.toISOString().substr(0, 11);
      dateString += date.toTimeString().substr(0, 8);
      resultXml = resultXml.replace('0000-00-00T00:00:00', dateString);

      // Replace \n with \r\n to be the same as a BP+
      var resultXmlFixed = resultXml.replace(/\n/g, '\r\n');
      
      // Update the CRC
      var crc8 = new CRC8();
      var checksum = crc8.checksum(resultXmlHeader + resultXmlFixed.trim());

      var resultXmlSize = '|_XML_Size79734 ' + checksum + '_|\r\n';
      
      this._notifyString('receive', resultXmlSize + resultXmlHeader + resultXmlFixed);

      this._notifyString('receive', 'M 02\r\n');
    }
  }
}

